ALTER TABLE "core"."assignments" DROP CONSTRAINT "assignments_quiz_check", ADD CONSTRAINT "assignments_quiz_check" CHECK ((submission_format = 'quiz') = (quiz_keep is not null and quiz_reveal is not null) and (quiz_attempts is null or quiz_attempts between 1 and 10) and (quiz_keep is null or quiz_keep in ('highest', 'latest', 'average', 'first')) and (quiz_reveal is null or quiz_reveal in ('answers', 'feedback', 'marks', 'returned')));